import re
from pathlib import Path
from typing import Any, Dict, Iterable, List, Optional


def _strip_extension(filename: str) -> str:
    name = Path(filename).name
    if "." not in name:
        return name
    return name.rsplit(".", 1)[0]


def _apply_camel_case_boundaries(text: str) -> str:
    pattern = re.compile(r"(?<=[a-z0-9])(?=[A-Z])")
    return pattern.sub(" ", text)


def tokenize_filename(filename: str, rules: Optional[Dict[str, Any]] = None) -> List[str]:
    """Tokenize a filename into normalized tokens based on rules."""

    base = _strip_extension(filename)
    base = _apply_camel_case_boundaries(base)
    token_delimiters: List[str]
    normalize_case = "lower"
    if rules is not None:
        token_delimiters = rules.get("token_delimiters") or ["_", "-", " "]
        normalize_case = rules.get("case") or "lower"
    else:
        token_delimiters = ["_", "-", " "]
    pattern = "|".join(re.escape(d) for d in token_delimiters)
    if not pattern:
        raw_tokens = [base]
    else:
        raw_tokens = re.split(pattern, base)
    tokens = [t.strip() for t in raw_tokens if t and t.strip()]
    if normalize_case == "lower":
        tokens = [t.lower() for t in tokens]
    return tokens


def extract_fields(
    filename: str, patterns: Optional[Iterable[Dict[str, Any]]] = None
) -> Dict[str, str]:
    """Extract structured fields from a filename using regex patterns."""

    if patterns is None:
        return {}
    base = _strip_extension(filename)
    fields: Dict[str, str] = {}
    for pattern in patterns:
        name = pattern.get("name")
        regex = pattern.get("regex")
        if not isinstance(name, str) or not isinstance(regex, str):
